if(region <> "" and not isnull(region))
{
	pkgDiscountTable = get(regionToPackageDiscount,region);
	resultsPkgChoice = bmql("SELECT package_header_id,package_revision,item_number,qty,mandatory,frozen_list_price,startDate,endDate FROM $pkgDiscountTable where package_header_id=$packageIDNumber and package_revision=$packageRev  and standAlone='Y' order by package_revision desc");

	for result in resultsPkgChoice{
	   if( isnull(get(result,"startDate"))){
	   strtDate =minusdays(getCurrentDate,1);
	     }
	   else
	   {
	    strtDate =strtojavadate(get(result,"startDate"),"yyyy-MM-dd");
	    }


	   if( isnull(get(result,"endDate")) or get(result,"endDate")==""){
	   endDate  =adddays(getCurrentDate,9999);
	    }
	   else{
	   endDate  =strtojavadate(get(result,"endDate"),"yyyy-MM-dd");
	   }

	  dateDiffendDate = comparedates(getCurrentDate ,endDate);
	  dateDiffsrtDate = comparedates(getCurrentDate ,strtDate);
         if(dateDiffendDate==-1 AND (dateDiffsrtDate==1 OR dateDiffsrtDate==0)){
		itemNumber = get(result,"item_number");
		pkgQty= get(result,"qty");
		mandatoryItem = get(result,"mandatory");
		price = get(result,"frozen_list_price");

		returnVal = returnVal +  itemNumber +hashSep + pkgQty + hashSep + mandatoryItem + hashSep + price +"$$$";
