			   //building return string
			   for data in  dataTableRecordSets{
				returnVal = returnVal + get(data,"AttrName") + recSep; 

			   }
			 }

	}
	else{
		//fetching data table record
		dataTableRecordSets = BMQL("SELECT distinct AttrName FROM $attrSeqTableName WHERE CPQModel  IN $cpqModelArry");


		//building return string
		for data in  dataTableRecordSets{
		    returnVal = returnVal + get(data,"AttrName") + recSep; 
		}
	}
}
else{
	//checking whether base model is set or not
	if(not isnull(modelSelectionbaseModel_astro) AND modelSelectionbaseModel_astro<>"" AND modelSelectionbaseModel_astro<>" "){
	   //fetching data table record
	   dataTableRecordSets = BMQL("SELECT distinct AttrName FROM $attrSeqTableName WHERE CPQModel=$cpqModel and BaseModel =$modelSelectionbaseModel_astro");
	   //print dataTableRecordSets;
	}
	else{
	   //fetching data table record
	   dataTableRecordSets = BMQL("SELECT distinct AttrName FROM $attrSeqTableName WHERE CPQModel=$cpqModel"); //print dataTableRecordSets;
	}

	//building return string
	for data in  dataTableRecordSets{
	    returnVal = returnVal + get(data,"AttrName") + recSep; 
	}
}



return returnVal;

