BaseBundlesAry_astro","existingSystemRelease_astro","systemRelease_astro","msGatewayTypeAry_astro","modelSelectionFrequencyBandMsl_astro","customerTypeDMSO_astro","deactivationMethodTypeDMSO_astro","astroDevices","productSelectionDMSO_astro","productSelectionProduct_all","howManyClientsWillBeAccessingTheCluster_astro","howManyClustersAreBeingOrdered_astro","pleaseEnterEmailAddressForLicenses_astro","isThisANewDispatchConsoleOrAnAddOn_astro","enterTheStartDateOfSubscription_astro","enterTheExpirationDateOfTheSubscriptionContract_astro","howManyAdditionalYearsDoYouWantInTheSubscriptionContract_astro","makeModelSelection_KVL5000_astro","solutionType_astro","modelSelectionMultiplexerType_astro","modelSelectionDEKSMType_astro" ,"currentASTROSystemRelease_astro" ,"modelSelectionOrderTypeMsl_astro","aPXTransportableBaseStation_astro","whelenMotorolaSiren_astro","routerFirewallModelSelection_astro","approximateQuantityOfOrder_astro","mountType_astro","operatingFrequencyBand_astro"};
modFilter     = string[];
fetchVals     = 0;

if (hiddenSeriesModelsMasterString_all <>""){
	selModel  = upper(productSelectionProduct_all);
}
else{
	selModel  = upper(_bm_model_variable_name);
}

//Checking if it is a series model
if(productSelectionProduct_all<>"" and productSelectionProduct_all<>" " and not isnull(productSelectionProduct_all))
{
	selModel = productSelectionProduct_all;
}

/* Dynamic Table - Ravi Ranjan begins */
whiteListTableName = "whitelist";
udccTableName = "newCountryRegMapping";
if(not isnull(dataTableList_astro) AND dataTableList_astro<>""){
	dataTableJson = json(dataTableList_astro);
    whiteListTableName = jsonget(dataTableJson,"WHITE_LIST");
	udccTableName = jsonget(dataTableJson,"NEW_COUNTRY_REGION_MAP");
}
if(isnull(whiteListTableName) OR whiteListTableName==""){
	whiteListTableName = "whitelist";
}
if(isnull(udccTableName) OR udccTableName==""){
	udccTableName = "newCountryRegMapping";
}
/* Dynamic Table - Ravi Ranjan ends */

//print selModel;
if(productSelectionProduct_all<>"" and productSelectionProduct_all<>" " and not isnull(productSelectionProduct_all)){

	//Added a condition for APXNEXT
	if(productSelectionProduct_all=="APX NEXT SINGLE" OR productSelectionProduct_all=="APX NEXT MULTI" OR productSelectionProduct_all=="APX NEXT XE MULTI"){
	    selModel="APXNEXT_BOM";
	}
	//Added a condition for APX NEXT SINGLE
	elif(productSelectionProduct_all=="APX NEXT SINGLE BAND" OR productSelectionProduct_all=="APX NEXT XE SINGLE BAND"){
	    selModel="APXNEXTSINGLE";
	}
	//Added a condition for APX NEXT INTERNATIONAL
	elif(productSelectionProduct_all=="APX NEXT INTL"){
	    selModel="APXNEXTINTL";
	}
	//Added a condition for APX NEXT Single Band INTERNATIONAL
	elif(productSelectionProduct_all=="APX NEXT SINGLE INTL"){
	    selModel="APXNEXTSINGLEINTL";
	}
	//Added a condition for APX NEXT XN All band
	elif(productSelectionProduct_all=="APX NEXT XN ALL"){
		selModel="APXNEXTXNALL";
	}	
	//Added a condition for APX NEXT XN Single Band
	elif(productSelectionProduct_all=="APX NEXT XN SINGLE BAND"){
		selModel="APXNEXTXNSINGLE";
	}
	//Added a condition for APX NEXT INTL FED
	elif(productSelectionProduct_all=="APX NEXT INTL FED"){
		selModel ="APXNEXTINTLFED";
	}
	//Added a condition for APX NEXT ENHANCED
	elif(productSelectionProduct_all=="APX NEXT ENHANCED" OR productSelectionProduct_all=="APX NEXT XE 4G LTE PLUS 5G"){
		selModel ="APXNEXTENHANCED";
	}
	elif(productSelectionProduct_all=="APX N70" OR productSelectionProduct_all=="APX N70XE"){
         	selModel ="APXN70_BOM";
        }// CXTB67: Added for N70 model

	 else{
         selModel = productSelectionProduct_all;
        }

}
//fetching record based on base model and udcc from udccTableNameTable
regionVals = string[];
notAllowed=string[];
onlyAllowed = 0;
evalFlag = 0;

/* Single BMQL: pull UDCC-specific rows + region-default rows */
rows = bmql("select value, ruleType, UDCC from $udccTableName where model = $selModel and partNumber is null and ((UDCC = $udC) or (UDCC is null and region = $modelSelectionRegion_astro))");
for r in rows {
  if (NOT ISNULL(get(r,"UDCC"))) {
    if (upper(get(r,"ruleType")) == "ALLOW") {
      append(modFilter, get(r,"value"));
      onlyAllowed = 1;
      evalFlag = 1;
    } else {
      append(notAllowed, get(r,"value"));
    }
  } else {
    append(regionVals, get(r,"value"));
  }
}

/* If no UDCC ALLOW, add region defaults excluding UDCC non-ALLOW values */
if (onlyAllowed < 1) {
  for v in regionVals {
    if (findinarray(notAllowed, v) == -1) {
      append(modFilter, v);
      evalFlag = 1;
    }
  }
}

if (evalFlag > 0) {
  eval = true;
}

//fetching data from data table and building return string  
dataTableRecordSets=bmql("select CPQModel,BaseModel,optionOrReqFlag,attr1,val1,attr2,val2,attr3,val3,attr4,val4,attr5,val5,attr6,val6,attr7,val7 from $whiteListTableName where (CPQModel = $selModel OR CPQModel='APXNEXT_BOM') AND (attr1 in $filter or attr1 is null ) AND (attr2 in $filter or attr2 is null ) AND (attr3 in $filter or attr3 is null ) AND (attr4 in $filter or attr4 is null ) AND (attr5 in $filter or attr5 is null ) AND (attr6 in $filter or attr6 is null ) AND (attr7 in $filter or attr7 is null )");
evalFlag = 0;

//Use modFilter condition when eval flag is true
for data in dataTableRecordSets {

  if(eval AND findinarray(modFilter, get(data,"BaseModel")) == -1){
    continue;
  }

  evalFlag = 1;

  returnVal = returnVal +"CPQModel"+ recSep+get(data,"CPQModel")+recSep+"REQFLAG"+recSep+get(data,"optionOrReqFlag")+recSep+"BaseModel"+ recSep+get(data,"BaseModel")+recSep;

  if(get(data,"attr1")<>""){ returnVal = returnVal +get(data,"attr1") + recSep + get(data,"val1") + recSep; }
  if(get(data,"attr2")<>""){ returnVal = returnVal +get(data,"attr2") + recSep + get(data,"val2") + recSep; }
  if(get(data,"attr3")<>""){ returnVal = returnVal +get(data,"attr3") + recSep + get(data,"val3") + recSep; }
  if(get(data,"attr4")<>""){ returnVal = returnVal +get(data,"attr4") + recSep + get(data,"val4") + recSep; }
  if(get(data,"attr5")<>""){ returnVal = returnVal +get(data,"attr5") + recSep + get(data,"val5") + recSep; }
  if(get(data,"attr6")<>""){ returnVal = returnVal +get(data,"attr6") + recSep + get(data,"val6") + recSep; }
  if(get(data,"attr7")<>""){ returnVal = returnVal +get(data,"attr7") + recSep + get(data,"val7") + recSep; }

  returnVal=substring(returnVal,0,len(returnVal)-3)+rowSep;
}

// Considering all the records if the above condition fails
if(evalFlag == 0){

  for data in dataTableRecordSets{

    returnVal = returnVal +"CPQModel"+ recSep+get(data,"CPQModel")+recSep+"REQFLAG"+recSep+get(data,"optionOrReqFlag")+recSep+"BaseModel"+ recSep+get(data,"BaseModel")+recSep;

    if(get(data,"attr1")<>""){ returnVal = returnVal +get(data,"attr1") + recSep + get(data,"val1") + recSep; }
    if(get(data,"attr2")<>""){ returnVal = returnVal +get(data,"attr2") + recSep + get(data,"val2") + recSep; }
    if(get(data,"attr3")<>""){ returnVal = returnVal +get(data,"attr3") + recSep + get(data,"val3") + recSep; }
    if(get(data,"attr4")<>""){ returnVal = returnVal +get(data,"attr4") + recSep + get(data,"val4") + recSep; }
    if(get(data,"attr5")<>""){ returnVal = returnVal +get(data,"attr5") + recSep + get(data,"val5") + recSep; }
    if(get(data,"attr6")<>""){ returnVal = returnVal +get(data,"attr6") + recSep + get(data,"val6") + recSep; }
    if(get(data,"attr7")<>""){ returnVal = returnVal +get(data,"attr7") + recSep + get(data,"val7") + recSep; }

    returnVal=substring(returnVal,0,len(returnVal)-3)+rowSep;
  }
}
return returnVal;

