	quantityDict = dict("string");
	DELIM3 = get(CONSTANTS,"CONFIG_DELIM3");
	DELIM4 = get(CONSTANTS,"CONFIG_DELIM4");
	tempStr = split(nonMandatoryPartsListString_all,DELIM4); //Split the commerce string and create dictionary with Part number as Key 
	for str in tempStr{
		val = split(str,DELIM3);
		if(val[0]<>"" and not(isnull(val[0]))){
			put(quantityDict,val[0],val[1]);
		}

	}
	//print quantityDict;

	for each in arrLength{ // Loop through the accessory array and find if the part number key exists in the qty string. 
		if(containskey(quantityDict,relatedServicePartsAry_astro[each])){
			qtyArr[each] = atoi(get(quantityDict,relatedServicePartsAry_astro[each]));
		}
