			tempValHolderStrAry  = split(str,hidddenRecordSeparator_allFamilly);
			put(isSelectedDict,tempValHolderStrAry[0],atoi(tempValHolderStrAry[3]));
			put(posDict,tempValHolderStrAry[0],pos);
		}
	} 
	if(not(isempty(keys(isSelectedDict))))
	{
		valFlag = 1;
		valuesKeys = keys(isSelectedDict);
		for cnt in loop{
			if(findinarray(valuesKeys,relatedServicePartsAry_astro[cnt])<>-1){
				val = get(isSelectedDict,relatedServicePartsAry_astro[cnt]);
				append(returnVal,val);
