retVal = "<table class=\"bom-table\"><thead><tr><th class=\"Description-header\">Option Class</th><th class=\"Description-header\">Option</th></tr></thead><tbody>";

itemsFlag = false;
partsArr = string[];
partsDescDict = dict("string");

pkgJsonObj = json();
if(packageJsonData<>""){
  pkgJsonObj = json(packageJsonData);
    /* Added by Ravi to remove the defaults key from Json string */
  if(not isnull(jsonget(pkgJsonObj,"defaults"))){
   jsonremove(pkgJsonObj,"defaults");
  }
  // 18/11/2025 : JGFN73 : To remove bomVarNames from Json string - starts
  if(not isnull(jsonget(pkgJsonObj,"bomVarNames"))){
   jsonremove(pkgJsonObj,"bomVarNames");
  }
  // 18/11/2025 : JGFN73 : To remove bomVarNames from Json string - ends
  keys = jsonkeys(pkgJsonObj,true);
  for i in keys{
    splitBy = "";
    jsonOption = jsonget(pkgJsonObj,i);
    if(find(jsonOption,",")==-1){
     splitBy = "~";
    }
    else{
     splitBy = ",";
    }
    optionValAry = split(jsonOption,splitBy);
    cnt = 0;
    itemsFlag=false; // Added by JGFN73 for preventing extra items in parts list
    for aryData in optionValAry{
     if(cnt==0 AND i <> "Items"){
      retVal = retVal + "<tr><td class=\"Description-cell\">"+i+"</td><td class=\"Description-cell\">"+aryData+"</td></tr>";
     }elif(cnt <> 0 AND NOT itemsFlag){
      retVal = retVal + "<tr><td class=\"Description-cell\"></td><td class=\"Description-cell\">"+aryData+"</td></tr>";
     }

     if(cnt==0){
      if(i=="Items"){
       itemsFlag = true;
      // print aryData;
       append(partsArr, aryData);
      }
      //retVal = retVal + "<tr><td class=\"Description-cell\">"+i+"</td><td class=\"Description-cell\">"+aryData+"</td></tr>";
     }
     if(itemsFlag AND cnt <> 0){
      //print aryData;
      append(partsArr, aryData);
      //retVal = retVal + "<tr><td class=\"Description-cell\"></td><td class=\"Description-cell\">"+aryData+"</td></tr>";
     }


     cnt = cnt + 1;
    }
  }
}

retVal = retVal + "</tbody></table><p/>";

retVal = retVal + "<table class=\"bom-table\"><thead><tr><th class=\"Description-header\">Item</th><th class=\"Description-header\">Description</th></tr></thead><tbody>";

