	//return "";
//}

partsDesc = bmql("SELECT part_number, description FROM _parts WHERE part_number IN $partsArr");
//print partsDesc;
for desc in partsDesc{
	put(partsDescDict, get(desc, "part_number"), get(desc, "description"));
}

for part in partsArr{
	retVal = retVal + "<tr><td class=\"Description-cell\">"+ part +"</td><td class=\"Description-cell\">"+get(partsDescDict, part)+"</td></tr>";
}

retVal = retVal + "</tbody></table>";

return retVal;

