/**
This rule will set default value for attribute

==================================Change Log============================================
Name        Date    Comments
-----------------------------------------------------------------------------------------

vamsi     3/27/17  Created
==================================End of Change Log=====================================

**/

pkgChoiceString = packageChoiceString;
splitEachRecord = string[];
accyParts = string[];
quantityArr = string[];
qtyArr = integer[];
if(hiddenAccesoriesMasterString_astro == ""){
	return qtyArr;
}	
partToQty = dict("string");
if (endswith(pkgChoiceString,"$$$")){
	pkgChoiceString = substring(pkgChoiceString,0,len(pkgChoiceString)-3);
}
splitPkgString = split(pkgChoiceString,"$$$");
//looping over package choice string
for eachRecord in splitPkgString{
	splitEachRecord = split(eachRecord,"@@@");
	if(splitEachRecord[0] == "solutionCategoryParts_astro" AND findinarray(accyParts,splitEachRecord[1])==-1){
		append(accyParts, splitEachRecord[1]); 
	}
	if(splitEachRecord[0] == "solutionCategoryQuantity_astro"){
		append(quantityArr, splitEachRecord[1]); 
	}	
}
partssize = range(sizeofarray(accyParts));
for i in partssize{
	put(partToQty, accyParts[i],quantityArr[i]);
}
size = range(solutionCategoryArrayControl_astro);
for i in size{
	if(findinarray(accyParts, solutionCategoryParts_astro[i])<>-1){
		append(qtyArr, atoi(get(partToQty,solutionCategoryParts_astro[i])));
	}
	else{
		append(qtyArr,0);
	}
}			
return qtyArr;

