//calling functon and returning user selectable attributes
stringvals =util.getConstraintVals(inputParam, filterCriteria);

if (endswith(stringvals,"|^|")){
stringvals=substring(stringvals,1,len(stringvals)-3);
}


finalValArray = SPLIT(stringvals,"|^|");

for val in finalValArray{
  valindex =findinarray(finalvalsArray,val);
  if (valindex==-1){
      append(finalvalsArray,val);
  }
} 


if(sizeofArray(finalvalsArray)==1){
     return finalvalsArray[0];
}
else{
     return "*";
} 
}
return "*";

