        if(NOT ISNULL(nonFreqValue) OR nonFreqValue <> "" OR nonFreqValue <>"null"){ //Check if nonFreqValue is not null, empty, or "null"
            jsonToArray=split(nonFreqValue,","); //Split the nonFreqValue into an array using commas as delimiters
            if(findinarray(part,jsonToArray[0])<>-1){ //Check if "part" exists in the array
                print jsonToArray[0];
                var=remove(jsonToArray,0); //Remove the first element from the array
                arrayToString=join(jsonToArray,","); //Join the remaining elements of the array back into a string
                nonFreqParametricDataTemplate = replace(attributesPayloadTemplate,"{{VariableName}}","nonFrequencyParametricData");
                nonFreqParametricDataTemplate = replace(nonFreqParametricDataTemplate,"{{Value}}",arrayToString);
            }
        }
}
/*The above code is to remove the part number from the beginning of the string of nonfrequency pd data - end*/


bomDataOccTemplate = replace(attributesPayloadTemplate,"{{VariableName}}","bomDataOcc");
