//Declaring required variables 
inputParam     = dict("string");
filterCriteria = string[];
returnVal      = "*";
optionalReqFlag    ="";
finalvalsArray=string[];

//setting up dictionary
put(inputParam,"Constrain Master String",hiddenConstraintMasterStringForBaseModel_astro);
put(inputParam,"recSep",hiddenRowSeparator_allFamily);
put(inputParam,"rowSep",hidddenRecordSeparator_allFamilly);
put(inputParam,"Base Model",upper(_bm_model_variable_name));
put(inputParam,"Attribute Variable Name","modelSelectionFrequencyBands_astro");
put(inputParam,"Attribute UI Sequence",hiddenUISequenceForModelSelection_astro);

optionalReqFlagArray=SPLIT(hiddenUISequenceForModelSelection_astro,hidddenRecordSeparator_allFamilly);
valindex             =findinarray(optionalReqFlagArray,"modelSelectionFrequencyBands_astro");


if (valindex<>-1){
optionalReqFlag     = optionalReqFlagArray[valindex+2];
}
else
{
optionalReqFlag     ="O";
}

if(optionalReqFlag <> "O") {
//model selection attributes
if(not isnull(modelSelectionRegion_astro) AND modelSelectionRegion_astro<>"" AND modelSelectionRegion_astro<>" "){
   append(filterCriteria,"modelSelectionRegion_astro");
   append(filterCriteria,modelSelectionRegion_astro);
} 

if(not isnull(ultimateDestinationCountry) AND ultimateDestinationCountry<>"" AND ultimateDestinationCountry<>" "){
   append(filterCriteria,"ultimateDestinationCountry");
   append(filterCriteria,ultimateDestinationCountry);
} 
if(not isnull(modelSelectionFrequencyBands_astro) AND modelSelectionFrequencyBands_astro<>"" AND modelSelectionFrequencyBands_astro<>" "){
   append(filterCriteria,"modelSelectionFrequencyBands_astro");
   append(filterCriteria,modelSelectionFrequencyBands_astro);
} 
if(not isnull(modelSelectionKeypadType_astro) AND modelSelectionKeypadType_astro<>"" AND modelSelectionKeypadType_astro<>" "){
   append(filterCriteria,"modelSelectionKeypadType_astro");
   append(filterCriteria,modelSelectionKeypadType_astro);
}

//calling functon and returning user selectable attributes
stringVals =util.getConstraintVals(inputParam, filterCriteria);

if (endswith(stringvals,"|^|")){
stringvals=substring(stringvals,1,len(stringvals)-3);
}


finalValArray = SPLIT(stringvals,"|^|");

for val in finalValArray{
  valindex =findinarray(finalvalsArray,val);
  if (valindex==-1){
      append(finalvalsArray,val);
  }
} 

if(sizeofArray(finalvalsArray)==1 AND productSelectionProduct_all <> "APX4000XH"){
     return finalvalsArray[0];
}
else{
     return "*";
} 
}
return "*";

