splitstringArray = SPLIT(hiddenMasterStringForAstroPortable_astro,hidddenRecordSeparator_allFamilly);
valindex         = findinarray(splitstringArray,"modelSelectionmadeInAmerica");


	if(valindex ==-1){

 		 isHidden = TRUE;
	}
	else {

		// Changed on Aug 16th, Jon, to fix APX8000 MIA showing up too early
	 	if(modelSelectionbaseModel_astro=="" OR hiddenConstraintMasterString_astro==""){
	  			return TRUE;
	  			 //isHidden = TRUE;
	 	}   

	        elif(isPrevUser=="YES" OR customerType == "FEDERAL"){

			    //Condition for APX900 Model
			   if(_bm_model_variable_name=="aPX900") {
			      isHidden = TRUE;
			   } 
			   //Condition for APX8500(Do not enable for M37TXS9PW1AN.)

			    elif(modelSelectionbaseModel_astro=="M37TXS9PW1AN") {
	   			isHidden = TRUE;
			     }

			     //Condition for APX8000 Model
			     elif((_bm_model_variable_name=="aPX8000Series") AND ((customerType =="WMATA") AND (modelselectionKeypadType_astro=="FULL KEYPAD"))){
			   isHidden = FALSE;
			   }

			    //Condition for APX8000 Model
			   elif((_bm_model_variable_name=="aPX8000Series") AND ((customerType =="FEDERAL"))){
			   isHidden = FALSE;
			   }
			    //Condition for APX6000 and APX5000 Model
			   elif(_bm_model_variable_name=="aPX60005000Series") {
			    if((modelSelectionbaseModel_astro=="H98UCD9PW5BNI") OR (modelSelectionbaseModel_astro=="H98UCF9PW6BNI") OR (modelSelectionbaseModel_astro=="H98UCH9PW7BNI") OR 
		  	      (modelSelectionbaseModel_astro=="H98KGD9PW5BNI") OR (modelSelectionbaseModel_astro=="H98KGF9PW6BNI") OR (modelSelectionbaseModel_astro=="H98KGH9PW7BNI") OR
		              (modelSelectionbaseModel_astro=="H98QDD9PW5BNI") OR (modelSelectionbaseModel_astro=="H98QDF9PW6BNI") OR (modelSelectionbaseModel_astro=="H98QDH9PW7BNI") OR
		              (modelSelectionbaseModel_astro=="H98SDD9PW5BNI") OR (modelSelectionbaseModel_astro=="H98SDF9PW6BNI") OR (modelSelectionbaseModel_astro=="H98SDH9PW7BNI")){

			      isHidden = TRUE;
			   }
			   else{

			   isHidden = FALSE;
			   }
			}

			  else{
			  isHidden= FALSE;  
		 	   }
		 } 	

		 elif(isPrevUser=="NO" OR customerType == "WMATA"){

		     //Condition for APX8000 Model
		    if((_bm_model_variable_name=="aPX8000Series") AND ((customerType =="WMATA") AND (modelselectionKeypadType_astro=="FULL KEYPAD"))){
			   isHidden = FALSE;
			   }

			   else{
			   isHidden= TRUE;  
			   }
		  	//isHidden= FALSE;  
		  }		  
	}
return isHidden;

