==================================Change Log============================================
Name        Date    Comments
-----------------------------------------------------------------------------------------

Shreyas 12/09/15 Updated
Ravi    03/10/16 Added optional/required logic and duplicates issue fixed
==================================End of Change Log=====================================

**/
//Declaring required variables 
filterCriteria = string[];
inputParam     = dict("string");
retval         ="*";
optionalReqFlag ="";
finalvalsArray   =string[];
//setting up dictionary
put(inputParam,"Constrain Master String",hiddenConstraintMasterString_astro);
put(inputParam,"recSep",hiddenRowSeparator_allFamily);
put(inputParam,"rowSep",hidddenRecordSeparator_allFamilly);
put(inputParam,"Base Model",modelSelectionbaseModel_astro);
put(inputParam,"Attribute Variable Name","configurationType_astro");
put(inputParam,"Attribute UI Sequence",hiddenUIsequenceMasterString_astro);

optionalReqFlagArray=SPLIT(hiddenUIsequenceMasterString_astro,hidddenRecordSeparator_allFamilly);
valindex             =findinarray(optionalReqFlagArray,"configurationType_astro");


if (valindex<>-1){
optionalReqFlag     = optionalReqFlagArray[valindex+2];
}
else
{
optionalReqFlag     ="O";
}

if(optionalReqFlag <> "O")   {
//Geography
if(not isnull(modelSelectionRegion_astro) AND modelSelectionRegion_astro<>"" AND modelSelectionRegion_astro<>" "){
   append(filterCriteria,"modelSelectionRegion_astro");
   append(filterCriteria,modelSelectionRegion_astro);
