allRecs = bmql("SELECT D.PartNumber, M.ItemCategory,M.ConfigAttrValue, M.ConfigAttrVarName, M.ConfigAttrValue1, M.ConfigAttrVarName4, M.ConfigAttrValue4 FROM Oracle_BomItemMap M INNER JOIN Oracle_BomItemDef D ON D.VariableName = M.BomItemVarName WHERE D.RootVariableName=$cpqModel AND M.ItemType = 'Related Services'");
