		 else{
			append(PartAry, get(rec,"PartNumber"));
		    	append(serCategoryTypeAry, get(rec,"ConfigAttrValue1"));
		    	append(serTypeAry, get(rec,"ItemCategory"));
		    	put(serSetDict,get(rec,"PartNumber"),get(rec,"ItemCategory"));
		    	put(serCategoryDict,get(rec,"PartNumber"),get(rec,"ConfigAttrValue1"));
		}    	
	}
    }
    else{
	    if(get(rec,"ConfigAttrVarName4")<>"" AND get(rec,"ConfigAttrVarName4")=="ultimateDestinationCountry"){		
    			if(get(rec,"ConfigAttrValue4")==ultimateDestinationCountry){
		    	    append(PartAry, get(rec,"PartNumber"));
					append(serCategoryTypeAry, get(rec,"ConfigAttrValue1"));
					append(serTypeAry, get(rec,"ItemCategory"));
					put(serSetDict,get(rec,"PartNumber"),get(rec,"ItemCategory"));
					put(serCategoryDict,get(rec,"PartNumber"),get(rec,"ConfigAttrValue1"));
