        desc = get(DescAry, PartAry[cnt]);
        filteredReturn = filteredReturn + PartAry[cnt] + recSep + serCategoryType + recSep + desc + recSep + "relatedServicesType_astro" + recSep + serType + rowSep;
    }
    cnt = cnt + 1;
}
if(relatedServicesType_astro<> ""){
arrLength  = range(relatedSoftwareAndServiceArrayControl_astro);
for each in arrLength{
    if(relatedServiceSelectAry_astro[each] and find(filteredReturn,relatedServicePartsAry_astro[each])==-1){
        desc = get(DescAry, PartAry[each]);
     	filteredReturn = filteredReturn+relatedServicePartsAry_astro[each] + recSep +get(serCategoryDict,relatedServicePartsAry_astro[each]) + recSep + desc + recSep + "relatedServicesType_astro" + recSep + get(serSetDict,relatedServicePartsAry_astro[each]) + rowSep;
    } 
}
}

// --- 4. Build UNFILTERED result (all) ---
cnt = 0;
unfilteredReturn = "";
for data in PartAry {
    serType = serTypeAry[cnt];
    serCategoryType = serCategoryTypeAry[cnt];
    desc = get(DescAry, PartAry[cnt]);
    unfilteredReturn = unfilteredReturn + PartAry[cnt] + recSep + serCategoryType + recSep + desc + recSep + "relatedServicesType_astro" + recSep + serType + rowSep;
    cnt = cnt + 1;
}

// --- 5. Combine and return ---
return filteredReturn + "_+_" + unfilteredReturn;

