	posDict        = dict("integer");
	valFlag        = 0;
	pos            = 0; 
	//setting flag based on advance rule
	loop = range(relatedSoftwareAndServiceArrayControl_astro);

	splitValHolderStr  = split(relatedServicesPreviousValues_astro,hiddenRowSeparator_allFamily);
	for str in splitValHolderStr{
		if(str<>""){

			pos = pos + 1;
			tempValHolderStrAry  = split(str,hidddenRecordSeparator_allFamilly);
			put(isSelectedDict,tempValHolderStrAry[0],atoi(tempValHolderStrAry[3]));
			put(posDict,tempValHolderStrAry[0],pos);
		}
	} 
	if(not(isempty(keys(isSelectedDict))))
	{
		valFlag = 1;
		valuesKeys = keys(isSelectedDict);
		for cnt in loop{
			if(findinarray(valuesKeys,relatedServicePartsAry_astro[cnt])<>-1){
				val = get(isSelectedDict,relatedServicePartsAry_astro[cnt]);
				append(returnVal,val);
			}
			else
			{
				append(returnVal,0);
			}			
		}
	}




	if(valFlag > 0){
	 return returnVal;
	}
	else{
	return relatedServiceQuantityAry_astro;
	}
}

