	        append(AccTypeAry, get(rec,"ItemCategory"));
	        put(solutionSetDict,get(rec,"PartNumber"),get(rec,"ItemCategory"));
	        put(partCategoryDict,get(rec,"PartNumber"),get(rec,"ConfigAttrValue1"));
	    }
	}

    else{
	    append(PartAry, get(rec,"PartNumber"));
	    append(AccCategoryTypeAry, get(rec,"ConfigAttrValue1"));
	    append(AccTypeAry, get(rec,"ItemCategory"));
	    put(solutionSetDict,get(rec,"PartNumber"),get(rec,"ItemCategory"));
	    put(partCategoryDict,get(rec,"PartNumber"),get(rec,"ConfigAttrValue1"));
	}  
}
print partAry;
// --- 2. Query ALL descriptions ONCE ---
DescAry = dict("string");
if(sizeofarray(PartAry) > 0) {
    partMasterRecordSets = bmql("select part_number, description from _parts where part_number in $PartAry");
    for part in partMasterRecordSets {
        put(DescAry, get(part,"part_number"), get(part,"description"));
    }
}

// --- 3. Build FILTERED result ---
solutionSet = string[];
filteredReturn = "";
if(accessoriesSolutionSet_astro <> ""){ 
    solutionSet = split(accessoriesSolutionSet_astro,"~");
}
cnt = 0;
for data in PartAry {
    accCategoryType = AccCategoryTypeAry[cnt];
    accType = AccTypeAry[cnt];
    // If filter supplied, only include if in filter
    if(sizeofarray(solutionSet)==0 or findinarray(solutionSet, accType)<> -1) {
        desc = get(DescAry, PartAry[cnt]);
        filteredReturn = filteredReturn + PartAry[cnt] + recSep + accCategoryType + recSep + desc + recSep + "accessoriesSolutionSet_astro" + recSep + accType + rowSep;
    }
    cnt = cnt + 1;
}
if(accessoriesSolutionSet_astro <> ""){
arrLength  = range(solutionCategoryArrayControl_astro);
for each in arrLength{
    if(solutionCategoryQuantity_astro[each]>0 and find(filteredReturn,solutionCategoryParts_astro[each])==-1){
        desc = get(DescAry, PartAry[each]);
     	filteredReturn = filteredReturn+solutionCategoryParts_astro[each] + recSep +get(partCategoryDict,solutionCategoryParts_astro[each]) + recSep + desc + recSep + "accessoriesSolutionSet_astro" + recSep + get(solutionSetDict,solutionCategoryParts_astro[each]) + rowSep;
    } 
}
}

// --- 4. Build UNFILTERED result (all) ---
cnt = 0;
unfilteredReturn = "";
for data in PartAry {
    accType = AccTypeAry[cnt];
    accCategoryType = AccCategoryTypeAry[cnt];
    desc = get(DescAry, PartAry[cnt]);
    unfilteredReturn = unfilteredReturn + PartAry[cnt] + recSep + accCategoryType + recSep + desc + recSep + "accessoriesSolutionSet_astro" + recSep + accType + rowSep;
    cnt = cnt + 1;
}

// --- 5. Combine and return ---
return filteredReturn + "_+_" + unfilteredReturn;

