			valFlag = 1;
			valuesKeys = keys(isSelectedDict);
			for cnt in loop{
				if(findinarray(valuesKeys,solutionCategoryParts_astro[cnt]+solutionCategory_astro[cnt])<>-1){
					val = get(isSelectedDict,solutionCategoryParts_astro[cnt]+solutionCategory_astro[cnt]);
