				if(util.getRCCFlag(upper(_bm_model_variable_name)) AND (findinarray(pdNameAry,"858-CLREGION")<>-1) AND ((ultimateDestinationCountry=="US") OR (productSelectionProduct_all=="APX NEXT INTL FED")))
				{
