					{
						returnVal = returnVal + "858-CLREGION"+ CONFIG_DELIM4 + "usfed" + CONFIG_DELIM3;
					}
					if ((isProvisioningRequiredInCloudEnv_astro=="NO") OR (isProvisioningRequiredInCloudEnv_astro==""))
					{
						returnVal = returnVal + "858-CLREGION"+ CONFIG_DELIM4 + "usgv" + CONFIG_DELIM3;
					}				
				}

				//PD for Cloud Region For CA
				if(util.getRCCFlag(upper(_bm_model_variable_name)) AND (findinarray(pdNameAry,"858-CLREGION")<>-1) AND (ultimateDestinationCountry=="CA"))
				{
					returnVal = returnVal + "858-CLREGION"+ CONFIG_DELIM4 + "cccs" + CONFIG_DELIM3;								
				}

				//PD for Product ID
				if(util.getRCCFlag(upper(_bm_model_variable_name)) AND (findinarray(pdNameAry,"801-PROD ID")<>-1) AND ((ultimateDestinationCountry=="US") OR (ultimateDestinationCountry=="CA") OR (productSelectionProduct_all=="APX NEXT INTL FED")))
				{
					returnVal = returnVal + "801-PROD ID"+ CONFIG_DELIM4 + "APXNEXT" + CONFIG_DELIM3;

				}

				returnVal = returnVal + CONFIG_DELIM1;	
			}


		}

}

return returnVal;

