AttrVarNamesArr = string[]  {"cBPQRCode_astro","numberOfSeats_astro","modelSelectionSubmersibleDeltaT_astro","modelSelectionHousing_astro","modelSelectionFrequencyBandMsl_astro","additionalSystemEnhancementFeatureType_astro","dMSDurationYears_astro","antennasType_astro","beltClipType_astro","operationModeType_astro","multikeyType_astro","systemEnhancementFeatureType_astro","secureEncryptionType_astro","advancedSystemKeyHardwareKey_astro","serviceTypeAdditionalDMSCoverage_astro","deviceManagementTraining_astro","trainTheTrainerTraining_astro","packingPackageType_astro","languageLanguageType_astro","documentationTestResultsRatedAudioPrintoutLabel_astro","extendRangeTo762764MHz_astro","systemID_astro"};
inputDict = dict("string");

familyname = "aSTRO25_bom";

records = bmql("SELECT variable_name,attribute_type,jetDisplayType FROM AttrMetaDataByFamily WHERE variable_name IN $AttrVarNamesArr AND product_family = $familyname");

for eachrecord in records {

    attrVarname = get(eachrecord,"variable_name");
    attrType =  get(eachrecord,"attribute_type");
    jetDisplayType = get(eachrecord,"jetDisplayType");

    put(inputDict,attrVarname,jetDisplayType);

}




return util.forcedsetRecommededConfigurationAttributes(inputDict);
